using System.IO;using System.Linq;using UnityEditor.SceneManagement;using UnityEngine;
public static class VerifyUpperMirror {
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/level2.unity");var level=Object.FindAnyObjectByType<FirstLevelRooms>();for(int i=0;i<level.rooms.Length;i++)level.rooms[i].SetActive(i==2);Physics2D.SyncTransforms();var mirror=level.rooms[2].GetComponentsInChildren<MirrorRicochetSurface>().OrderByDescending(m=>m.transform.position.y).First();var edge=mirror.GetComponent<EdgeCollider2D>();var mid=(Vector2)mirror.transform.TransformPoint((edge.points[0]+edge.points[1])*.5f);var origin=new Vector2(-3.5f,-.6f);var dir=(mid-origin).normalized;var hit=FirstLevelShotPath.Cast(origin,dir,.035f,10);var shot=FirstLevelShot.Create(origin,dir,null,null);File.WriteAllText("Tools/upper-mirror-result.txt","mirror="+mirror.name+" centre="+mid+" contact="+(hit.solid!=null?hit.solid.name:hit.mirror.name)+" distance="+hit.distance+" normal="+hit.normal+" reflections="+shot.Reflections+" finished="+shot.Finished+" final="+(shot!=null?shot.transform.position:Vector3.zero)+" direction="+shot.Direction+" colliders="+string.Join(";",level.rooms[2].GetComponentsInChildren<Collider2D>().Where(c=>c.bounds.Contains(mid)).Select(c=>c.name+" "+c.GetType().Name)));shot.Step(Vector2.Distance(origin,mid)+.5f);File.AppendAllText("Tools/upper-mirror-result.txt"," AFTER reflections="+shot.Reflections+" finished="+shot.Finished+" direction="+shot.Direction);if(shot.Reflections!=1 || !shot.Charged || shot.Finished)throw new System.Exception("Upper mirror did not reflect/charge the shot");
 }
}
